class DataProcessor:
    def filter(self, data, extra=None):
        result = []
        for item in data:
            if extra and item.get(extra['field']) == extra['value']:
                result.append(item)
        return result

    def sort(self, data, extra=None):
        key = extra.get('key') if extra else None
        reverse = extra.get('reverse', False) if extra else False
        return sorted(data, key=lambda x: x.get(key), reverse=reverse)

    def group(self, data, extra=None):
        groups = {}
        field = extra.get('field') if extra else None
        for item in data:
            k = item.get(field)
            if k not in groups:
                groups[k] = []
            groups[k].append(item)
        return groups

    def aggregate(self, data, extra=None):
        field = extra.get('field') if extra else None
        func = extra.get('func', 'sum') if extra else 'sum'
        values = [item.get(field, 0) for item in data]
        if func == 'sum':
            return sum(values)
        elif func == 'avg':
            return sum(values) / len(values) if values else 0
        elif func == 'min':
            return min(values) if values else None
        elif func == 'max':
            return max(values) if values else None
        raise ValueError(f'Unknown function: {func}')

def process(data, operation, extra=None):
    processor = DataProcessor()
    if operation == 'filter':
        return processor.filter(data, extra)
    elif operation == 'sort':
        return processor.sort(data, extra)
    elif operation == 'group':
        return processor.group(data, extra)
    elif operation == 'aggregate':
        return processor.aggregate(data, extra)
    raise ValueError(f'Unknown operation: {operation}')
